import {lazy, Suspense, useEffect, useMemo} from 'react'
import type {EntryPointProps} from 'react-relay'

import {useAppDispatch} from '../../../../../hooks/react-redux'
import Loader from '../../../../common/Loader/Loader'
import type {pipelineHeadBuildTypeFragment$key} from '../../hooks/__generated__/pipelineHeadBuildTypeFragment.graphql'
import {usePipelineId} from '../../hooks/pipeline'
import {useEditPipelineYAML} from '../EditPipelinePage.hooks'
import type {JobAgentRequirementsCloudImagesQuery} from '../SettingsSidebarContent/JobSettingsSidebar/JobAgentRequirements/__generated__/JobAgentRequirementsCloudImagesQuery.graphql'
import {pipelineYaml} from '../slices/EditPipelinePage.slices'

import EditPipelineYAMLContextProvider from './EditPipelineYAMLContext/EditPipelineYAMLContext'

import styles from './EditPipelineYAML.module.css'

const YamlEditor = lazy(
  () =>
    import(
      /* webpackChunkName: "YamlEditor" */
      './YamlEditor/YamlEditor'
    ),
)

type Props = {pipelineHeadBuildTypeKey: pipelineHeadBuildTypeFragment$key | null}
type Queries = {cloudImages: JobAgentRequirementsCloudImagesQuery}

function EditPipelineYAML({queries, props}: EntryPointProps<Queries, {}, Props, {}>) {
  const pipelineId = usePipelineId()
  const dispatch = useAppDispatch()
  const {yaml, isReadonly, yamlEditorValidateHandler, yamlEditorChangeHandler} =
    useEditPipelineYAML()
  const contextValue = useMemo(
    () => ({
      pipelineHeadBuildTypeKey: props.pipelineHeadBuildTypeKey,
      cloudImagesQueryRef: queries.cloudImages,
    }),
    [props, queries.cloudImages],
  )

  useEffect(
    () => () => {
      dispatch(pipelineYaml.actions.reset(pipelineId))
    },
    [dispatch, pipelineId],
  )

  return (
    <div className={styles.main}>
      {yaml != null && (
        <Suspense fallback={<Loader data-suspense-fallback />}>
          <EditPipelineYAMLContextProvider value={contextValue}>
            <YamlEditor
              onChange={yamlEditorChangeHandler}
              onValidate={yamlEditorValidateHandler}
              value={yaml}
              isReadonly={isReadonly}
            />
          </EditPipelineYAMLContextProvider>
        </Suspense>
      )}
    </div>
  )
}

export type EditPipelineYAMLComponent = typeof EditPipelineYAML

export default EditPipelineYAML
